const BREACHED_SET = new Set(BREACHED_PASSWORDS_DB.map(p => p.toLowerCase()));

function isBreachedPassword(password) {
  if (!password) return false;
  return BREACHED_SET.has(password.toLowerCase());
}

function getBreachFrequency(password) {
  if (!password) return 0;
  const lower = password.toLowerCase();
  if (BREACHED_SET.has(lower)) {
    // Simulated frequency score
    return Math.floor(Math.random() * 50000) + 1000;
  }
  return 0;
}

module.exports = {
  BREACHED_PASSWORDS_DB,
  isBreachedPassword,
  getBreachFrequency
};
